// === Tab: Crayon ===
class Crayon {
	constructor(pos, tpos, c, n, w, h, i, li) {
		this.pos = pos;
		this.tpos = tpos;
		this.otpos = createVector(tpos.x, tpos.y, tpos.z);
		this.c = c;
		this.n = n;
		this.w = w;
		this.h = h;
		this.a = 0;
		this.ta = random(PI / 2, 3 * PI / 2);
		this.id = i;
		this.li = li;
		this.lpos = createVector(0,0,0);
	}
	move() {
		this.pos.lerp(this.tpos, 0.2);
		this.a = lerp(this.a, this.ta, 0.1);
	}

	show() {
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		noStroke();
		specularMaterial(this.c);
		shininess(3);
		cylinder(this.w * 0.95, 2.2 * this.h);
		rotateY(this.a);
		if (brightness(window.color(color(this.c))) > 0) tint(this.c);
		else tint(50);
		texture(wrapper);
		cylinder(this.w, 2 * this.h, 16, 1, false, false);
		translate(0, -this.h - this.h / 20, 0);
		specularMaterial(this.c);
		shininess(10);
		noStroke();
		translate(0, -this.h / 6, 0);
		let m= createTruncatedCone(this.w *0.9, this.w*0.25, this.h / 3, 16, 1, false, true);
		rotateZ(PI);
		model(m)
		pop();
	}
}

