function shuffleCrayons() {
	for (var i = crayons.length - 1; i > 0; i--) {
		var j = Math.floor(Math.random() * (i + 1));
		[crayons[i].tpos.x, crayons[j].tpos.x] = [crayons[j].tpos.x, crayons[i].tpos.x];
		[crayons[i].tpos.z, crayons[j].tpos.z] = [crayons[j].tpos.z, crayons[i].tpos.z];
	}
}

